export const getMessagesListUrl = (channelId: string, params?: MessagesListParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/channels/${encodeURIComponent(String(channelId))}/messages?${stringifiedParams}`
    : `/api/channels/${encodeURIComponent(String(channelId))}/messages`;
};

